    /// FENCE-IDENTITY-1 regression: a callee whose RENDERED path ends in
    /// `::fence`/`::compiler_fence` (or is exactly that word) but whose identity
    /// is not the standard fence is a plain call — even with an argument that is
    /// a perfectly good ordering discriminant, which used to be PARSED as a real
    /// fence and lowered by `trust-cg-bridge` in place of the user's body.
    #[test]
    fn name_alone_never_makes_a_fence() {
        for name in [
            "trust_ir_build::FunctionBuilder::fence",
            "p2::B::fence",
            "mycrate::fence",
            "fence",
            "mycrate::compiler_fence",
            "compiler_fence",
            // A display path that LOOKS like the real one is still not identity.
            "std::sync::atomic::fence",
            "core::sync::atomic::compiler_fence",
        ] {
            for callee in [AtomicCalleeIdentity::NOT_SYSROOT, AtomicCalleeIdentity::SYSROOT_OTHER] {
                for args in [fence_order_args(AtomicOrdering::SeqCst), vec![], ptr_args()] {
                    assert_eq!(
                        parse_atomic_intrinsic_metadata(
                            name,
                            callee,
                            &args,
                            &default_dest(),
                            &default_span(),
                        ),
                        AtomicIntrinsicMetadata::NotAtomic,
                        "{name} under {callee:?} must not be read as a fence"
                    );
                }
            }
        }
    }

    /// FENCE-IDENTITY-1, Form B: the `atomic::atomic_` substring is display
    /// text; outside the authenticated sysroot it names a user function.
    #[test]
    fn display_forms_require_a_real_sysroot_callee() {
        for (name, args) in [
            (
                "mycrate::atomic::atomic_load",
                vec![ptr_args()[0].clone(), ordering_arg(AtomicOrdering::SeqCst)],
            ),
            ("mycrate::atomic::atomic_fence", fence_order_args(AtomicOrdering::SeqCst)),
            ("core::intrinsics::atomic_load_seqcst", ptr_args()),
        ] {
            assert_eq!(
                parse_atomic_intrinsic_metadata(
                    name,
                    AtomicCalleeIdentity::NOT_SYSROOT,
                    &args,
                    &default_dest(),
                    &default_span(),
                ),
                AtomicIntrinsicMetadata::NotAtomic,
                "{name}"
            );
        }
        // Control: the same display text from an authenticated sysroot callee
        // keeps its existing reading.
        assert!(
            parse_atomic_intrinsic(
                "core::intrinsics::atomic_load_seqcst",
                &ptr_args(),
                &default_dest(),
                &default_span()
            )
            .is_some()
        );
    }

    // --- All five orderings on a single operation ---

    #[test]
    fn all_orderings_for_xadd() {
        let orderings = [
            ("relaxed", AtomicOrdering::Relaxed),
            ("acquire", AtomicOrdering::Acquire),
            ("release", AtomicOrdering::Release),
            ("acqrel", AtomicOrdering::AcqRel),
            ("seqcst", AtomicOrdering::SeqCst),
        ];
        for (suffix, expected) in &orderings {
            let name = format!("core::intrinsics::atomic_xadd_{suffix}");
            let op =
                parse_atomic_intrinsic(&name, &ptr_val_args(), &default_dest(), &default_span())
                    .unwrap();
            assert_eq!(op.ordering, *expected, "xadd_{suffix} should be {expected:?}");
        }
    }

    // --- CAS ordering combinations ---

    #[test]
    fn cas_all_valid_combinations() {
        let cases = [
            ("seqcst_seqcst", AtomicOrdering::SeqCst, AtomicOrdering::SeqCst),
            ("seqcst_acquire", AtomicOrdering::SeqCst, AtomicOrdering::Acquire),
            ("seqcst_relaxed", AtomicOrdering::SeqCst, AtomicOrdering::Relaxed),
            ("acqrel_acquire", AtomicOrdering::AcqRel, AtomicOrdering::Acquire),
            ("acqrel_relaxed", AtomicOrdering::AcqRel, AtomicOrdering::Relaxed),
            ("acquire_acquire", AtomicOrdering::Acquire, AtomicOrdering::Acquire),
            ("acquire_relaxed", AtomicOrdering::Acquire, AtomicOrdering::Relaxed),
            ("release_relaxed", AtomicOrdering::Release, AtomicOrdering::Relaxed),
            ("relaxed_relaxed", AtomicOrdering::Relaxed, AtomicOrdering::Relaxed),
        ];
        for (suffix, exp_success, exp_failure) in &cases {
            let name = format!("core::intrinsics::atomic_cxchg_{suffix}");
            let op = parse_atomic_intrinsic(&name, &cas_args(), &default_dest(), &default_span())
                .unwrap();
            assert_eq!(op.ordering, *exp_success, "CAS {suffix} success");
            assert_eq!(op.failure_ordering, Some(*exp_failure), "CAS {suffix} failure");
        }
    }

