    #[test]
    fn analysis_only_statements_lower_to_metadata_noops() {
        let statements = synthetic_statement_shapes();

        assert!(
            matches!(statements.get("fake_read"), Some(Statement::Nop)),
            "fake read is borrow-check metadata and must lower to Nop, got {:?}",
            statements.get("fake_read")
        );

        assert!(
            matches!(statements.get("ascribe_user_type"), Some(Statement::Nop)),
            "user type ascription is type-check metadata and must lower to Nop, got {:?}",
            statements.get("ascribe_user_type")
        );

        assert!(
            matches!(statements.get("backward_incompatible_drop_hint"), Some(Statement::Nop)),
            "backward-incompatible drop hint is lint metadata and must lower to Nop, got {:?}",
            statements.get("backward_incompatible_drop_hint")
        );
    }

    #[test]
    fn analysis_only_terminators_lower_to_runtime_gotos() {
        let terminators = synthetic_terminator_shapes();

        assert!(
            matches!(terminators.get("false_edge"), Some(Terminator::Goto(BlockId(7)))),
            "FalseEdge must lower to its real runtime target, got {:?}",
            terminators.get("false_edge")
        );

        assert!(
            matches!(terminators.get("false_unwind"), Some(Terminator::Goto(BlockId(11)))),
            "FalseUnwind must lower to its real runtime target, got {:?}",
            terminators.get("false_unwind")
        );

        assert!(
            matches!(terminators.get("coroutine_drop"), Some(Terminator::Return)),
            "CoroutineDrop is terminal coroutine drop-glue return, got {:?}",
            terminators.get("coroutine_drop")
        );

        assert!(
            matches!(terminators.get("unwind_resume"), Some(Terminator::Resume)),
            "UnwindResume must lower to a no-obligation Resume sink (not Opaque/Unreachable), got {:?}",
            terminators.get("unwind_resume")
        );

        assert!(
            matches!(
                terminators.get("unwind_terminate"),
                Some(Terminator::Opaque { kind, targets, .. })
                    if kind.contains("UnwindTerminate") && targets.is_empty()
            ),
            "UnwindTerminate must remain distinct and fail closed until TrustIr has an abort sink, got {:?}",
            terminators.get("unwind_terminate")
        );
    }

    #[test]
    fn direct_bit_intrinsic_marker_requires_tcx_intrinsic_identity() {
        let callees = fixture_direct_callees();
        for intrinsic in ["ctpop", "cttz", "ctlz", "bswap", "bitreverse"] {
            let compiler_key = format!("compiler_intrinsic_{intrinsic}");
            let compiler_intrinsic =
                callees.get(&compiler_key).expect("compiler intrinsic wrapper extracted");
            assert_eq!(compiler_intrinsic.len(), 1, "expected one direct {intrinsic} call");
            assert!(
                compiler_intrinsic[0].starts_with(trust_types::TRUST_RUSTC_INTRINSIC_PATH_PREFIX),
                "TyCtxt-confirmed body-less {intrinsic} must carry the marker: {:?}",
                compiler_intrinsic
            );
            assert!(
                compiler_intrinsic[0].contains(&format!("intrinsics::{intrinsic}")),
                "the marker must preserve the diagnostic intrinsic path: {:?}",
                compiler_intrinsic
            );

            let source_key = format!("source_spelled_intrinsics_{intrinsic}");
            let source_spelled =
                callees.get(&source_key).expect("source-spelled wrapper extracted");
            assert_eq!(source_spelled.len(), 1, "expected one source-spelled {intrinsic} call");
            assert!(
                !source_spelled[0].starts_with(trust_types::TRUST_RUSTC_INTRINSIC_PATH_PREFIX),
                "an intrinsics::{intrinsic}-shaped source DefPath must remain unmarked: {:?}",
                source_spelled
            );
            assert!(
                source_spelled[0].ends_with(&format!("::intrinsics::{intrinsic}")),
                "negative control must retain its colliding textual suffix: {:?}",
                source_spelled
            );
        }
    }

    #[test]
    fn direct_unsigned_wrapping_marker_requires_tcx_primitive_inherent_identity() {
        let callees = fixture_direct_callees();
        for width in ["u8", "u16", "u32", "u64"] {
            for (suffix, method) in
                [("add", "wrapping_add"), ("sub", "wrapping_sub"), ("mul", "wrapping_mul")]
            {
                let caller = format!("compiler_wrapping_{width}_{suffix}");
                let extracted = callees.get(&caller).expect("unsigned wrapping caller extracted");
                assert_eq!(extracted.len(), 1, "expected one direct call from {caller}");
                assert!(
                    extracted[0]
                        .starts_with(trust_types::TRUST_RUSTC_TOTAL_PRIMITIVE_METHOD_PATH_PREFIX),
                    "TyCtxt-confirmed unsigned primitive {method} must carry the sealed method marker: {extracted:?}",
                );
                assert!(
                    !extracted[0].starts_with(trust_types::TRUST_RUSTC_INTRINSIC_PATH_PREFIX),
                    "a core library method must not impersonate a rustc intrinsic: {extracted:?}",
                );
                assert_eq!(
                    trust_types::RustcTotalPrimitiveMethod::classify(&extracted[0])
                        .map(trust_types::RustcTotalPrimitiveMethod::width),
                    Some(width.trim_start_matches('u').parse().expect("numeric width")),
                    "the marker grammar must preserve the exact admitted machine width",
                );
                assert!(
                    extracted[0].contains("core::num") && extracted[0].contains(method),
                    "the marker must preserve the authenticated primitive method path: {extracted:?}",
                );
            }
        }

        // Trust (TG14): the E6-only tree lane gains signed arithmetic;
        // the frozen unsigned recognizer must still decline these markers.
        for caller in [
            "excluded_wrapping_i8_add",
            "excluded_wrapping_i16_sub",
            "excluded_wrapping_i32_mul",
            "excluded_wrapping_i64_add",
        ] {
            let extracted = callees.get(caller).expect("signed wrapping caller extracted");
            assert_eq!(extracted.len(), 1);
            assert!(
                trust_types::e6_expr::tree::wrapping_primitive(&extracted[0]).is_some(),
                "signed arithmetic requires authenticated E6 identity: {caller}: {extracted:?}"
            );
            assert!(
                trust_types::RustcTotalPrimitiveMethod::classify(&extracted[0]).is_none(),
                "the frozen unsigned recognizer must remain unchanged"
            );
        }

        let composed = callees
            .get("compiler_wrapping_composed_u64")
            .expect("composed unsigned wrapping caller extracted");
        assert_eq!(composed.len(), 2, "the pre-optimization S4 chain must retain two calls");
        for callee in composed {
            assert!(
                trust_types::RustcTotalPrimitiveMethod::classify(callee)
                    .is_some_and(|method| method.width() == 64),
                "every node in the composed chain must carry exact sealed u64 identity: {composed:?}",
            );
        }

        for caller in [
            "excluded_wrapping_u128_add",
            "excluded_wrapping_usize_add",
            "excluded_wrapping_usize_mul",
            "excluded_wrapping_u128_mul",
            "excluded_wrapping_i128_add",
            "excluded_wrapping_ptr_add",
            "excluded_wrapping_add_signed",
            "excluded_wrapping_add_unsigned",
            "excluded_saturating_u64_add",
            "source_spelled_wrapping_add",
            "user_inherent_wrapping_sub",
            "user_wrong_signature_wrapping_add",
            "user_trait_wrapping_mul",
        ] {
            let extracted = callees.get(caller).expect("unsigned wrapping caller extracted");
            assert_eq!(extracted.len(), 1, "expected one direct call from {caller}");
            assert!(
                !extracted[0]
                    .starts_with(trust_types::TRUST_RUSTC_TOTAL_PRIMITIVE_METHOD_PATH_PREFIX),
                "excluded or lookalike method must remain unmarked ({caller}): {extracted:?}",
            );
        }

        for caller in [
            "excluded_wrapping_u128_add",
            "excluded_wrapping_usize_add",
            "excluded_wrapping_usize_mul",
            "excluded_wrapping_u128_mul",
            "excluded_wrapping_i128_add",
        ] {
            let extracted = callees.get(caller).expect("refutation wrapping caller extracted");
            assert!(
                trust_types::RustcWrappingRefutationMethod::classify(&extracted[0]).is_some(),
                "an exact non-E6 core wrapping add/sub/mul must retain sealed refutation \
                 identity: {caller}: {extracted:?}"
            );
        }

        for caller in [
            "excluded_wrapping_ptr_add",
            "excluded_wrapping_add_signed",
            "excluded_wrapping_add_unsigned",
            "excluded_saturating_u64_add",
            "source_spelled_wrapping_add",
            "user_inherent_wrapping_sub",
            "user_wrong_signature_wrapping_add",
            "user_trait_wrapping_mul",
        ] {
            let extracted = callees.get(caller).expect("wrapping negative caller extracted");
            assert!(
                !extracted[0]
                    .starts_with(trust_types::TRUST_RUSTC_WRAPPING_REFUTATION_METHOD_PATH_PREFIX),
                "an unsupported or source-authored lookalike must not receive refutation identity: \
                 {caller}: {extracted:?}"
            );
        }
    }

